		if req.SessionID != "" && snap.CacheHitRate > 0 {
			scores[snap.ID] *= (1.0 + 0.33*snap.CacheHitRate)
		}

		// SLO-aware load sensitivity
		if req.SLOClass == "realtime" && el > 1 {
			scores[snap.ID] *= 0.52
		} else if req.SLOClass == "interactive" && el > 3 {
			scores[snap.ID] *= 0.67
		}

