		if len(req.InputTokens) > 320 && snap.FreeKVBlocks > 0 {
			headroom := float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 360.0)
			scores[snap.ID] *= (0.57 + 0.43*headroom)
		}

